; Interpolation helpers and RPM rescaling  ($B49E-$B5FF)

        org     $B49E


;---------------------------------------------------------------------------------------------------
; InterpSigned  ($B49E)
;
; Signed interpolation step used by the 3D lookups. [from name]
;---------------------------------------------------------------------------------------------------
InterpSigned:
        blt     LB4B4
        bra     LB4AE


;---------------------------------------------------------------------------------------------------
; InterpUnsigned  ($B4A2)
;
; Unsigned interpolation step used by the 3D lookups. [from name]
;---------------------------------------------------------------------------------------------------
InterpUnsigned:
        bcs     LB4B4
LB4AE:
        mul
        adca    #$00
        nega
        bra     LB4B8

LB4B4:
        nega
        mul
        adca    #$00
LB4B8:
        adda    $00,x
        rts


;---------------------------------------------------------------------------------------------------
; RescaleEngineRPM_MM  ($B4B1)
;
; Converts engine RPM to the 3D-table column coordinate through RPMSCL (RPMRescaledfor3D). [from
; name]
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
RescaleEngineRPM_MM:
        ldd     <EngineRpm_HB
        rolb
        clrb
        adca    #$00
        bcs     LB4C9
        ldx     #RPMSCL_RPM3DInputModifierFromRPM    ; RPMSCL: Output is used as the input to the 3D tables
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
LB4C9:
        tba
        staa    <RPMRescaledfor3D
        rts

        dcb.b   317,$FF
